const raw = $json.output &&
            $json.output[0] &&
            $json.output[0].content &&
            $json.output[0].content[0]
  ? $json.output[0].content[0].text
  : undefined;

let ai = {};

if (typeof raw === 'string') {
  try {
    ai = JSON.parse(raw);
  } catch (e) {
    ai = {};
  }
} else if (raw && typeof raw === 'object') {
  ai = raw;
}

const prep = $('Prepare EspoCRM Lead Context').item.json;
const ext = $('Extract Reply Details').item.json;

// Map OpenAI intent to EXACT EspoCRM / routing values
const intentMap = {
  'High Intent': 'High Intent',
  'Interested': 'Interested',

  'More Information': 'Requesting Information',
  'Requesting Information': 'Requesting Information',

  'Meeting': 'Meeting Request',
  'Meeting Requested': 'Meeting Request',
  'Meeting Request': 'Meeting Request',

  'Callback Requested': 'Callback Request',
  'Callback Request': 'Callback Request',

  'Researching': 'Researching',

  'Not Interested': 'Not Interested',

  // IMPORTANT: Lost must stay Lost
  'Lost': 'Lost',

  'Unknown': 'Unclear',
  'Unclear': 'Unclear',

  'General Reply': 'Not Classified',
  'Not Classified': 'Not Classified'
};

const intent = intentMap[ai.Intent] || 'Not Classified';


// ----------------------------------------------------
// MEETING DATE / TIME
// ----------------------------------------------------

// Only keep meeting date/time when OpenAI actually returned them.
// Do NOT invent or default a meeting date/time.
const suggestedMeetingDate =
  ai.SuggestedMeetingDate &&
  typeof ai.SuggestedMeetingDate === 'string'
    ? ai.SuggestedMeetingDate.trim()
    : null;

const suggestedMeetingTime =
  ai.SuggestedMeetingTime &&
  typeof ai.SuggestedMeetingTime === 'string'
    ? ai.SuggestedMeetingTime.trim()
    : null;


// ----------------------------------------------------
// FINAL OUTPUT
// ----------------------------------------------------

return {
  EspoCRMRecordId: prep.EspoCRMRecordId,
  LeadName: prep.LeadName,
  CurrentLeadStatus: prep.CurrentLeadStatus,
  AssignedUser: prep.AssignedUser,

  SenderEmail: ext.SenderEmail,
  SenderName: ext.SenderName,
  Subject: ext.Subject,
  Message: ext.Message,
  MessageId: ext.MessageId,
  ReceivedAt: ext.ReceivedAt,

  Intent: intent,

  Sentiment:
    ai.Sentiment || 'Neutral',

  Priority:
    ai.Priority || 'Medium',

  MeetingRequested:
    ai.MeetingRequested === true ||
    intent === 'Meeting Request',

  CallbackRequested:
    ai.CallbackRequested === true ||
    intent === 'Callback Request',

  // Meeting scheduling fields
  SuggestedMeetingDate: suggestedMeetingDate,
  SuggestedMeetingTime: suggestedMeetingTime,

  RecommendedAction:
    ai.RecommendedAction || '',

  Summary:
    ai.Summary || ''
};

