const d = $json;

const intent = d.Intent || 'Not Classified';

let leadStatus = 'New';

// Built-in EspoCRM status.
// Start with the current status, then override only when appropriate.
let espoStatus = d.CurrentLeadStatus || 'New';

let needsMeeting = false;
let needsCallback = false;
let needsSlack = true;
let closeFollowUp = false;

// Automatic follow-up date
let followUpDate = null;

switch (intent) {

  case 'High Intent':
    leadStatus = 'Interested';
    espoStatus = 'New';

    followUpDate = DateTime.now()
      .setZone('Asia/Dubai')
      .plus({ days: 1 })
      .toFormat('yyyy-MM-dd');
    break;

  case 'Interested':
    leadStatus = 'Interested';
    espoStatus = 'New';

    followUpDate = DateTime.now()
      .setZone('Asia/Dubai')
      .plus({ days: 1 })
      .toFormat('yyyy-MM-dd');
    break;

  case 'Requesting Information':
    leadStatus = 'Follow-up Required';
    espoStatus = 'New';

    followUpDate = DateTime.now()
      .setZone('Asia/Dubai')
      .plus({ days: 1 })
      .toFormat('yyyy-MM-dd');
    break;

  case 'Meeting Request':
    leadStatus = 'Meeting Requested';
    espoStatus = 'New';
    needsMeeting = true;
    break;

  case 'Callback Request':
    leadStatus = 'Callback Requested';
    espoStatus = 'New';
    needsCallback = true;
    break;

  case 'Lost':
    leadStatus = 'Lost';
    espoStatus = 'Lost';
    closeFollowUp = true;
    followUpDate = null;
    break;

  case 'Not Interested':
    leadStatus = 'Not Interested';
    espoStatus = 'Lost';
    closeFollowUp = true;
    followUpDate = null;
    break;

  case 'Not Classified':
  case 'General Reply':
  default:
    // Keep existing status for unclear/general replies.
    leadStatus = d.CurrentLeadStatus || 'New';
    espoStatus = d.CurrentLeadStatus || 'New';
    break;
}

return {
  ...d,

  LeadStatusToSet: leadStatus,
  EspoStatusToSet: espoStatus,

  NeedsMeeting: needsMeeting,
  NeedsCallback: needsCallback,
  NeedsSlack: needsSlack,
  CloseFollowUp: closeFollowUp,

  FollowUpDateToSet: followUpDate,

  ActionType:
    needsMeeting
      ? 'Meeting'
      : needsCallback
      ? 'Callback'
      : 'Standard'
};

